#nullable enable // autogenerated

using System;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Bosses;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Bosses
{
    [AutoEntityBehaviourDefinition(VanillaBossNames.krakenTentacle)]
    public partial class KrakenTentacle : AIEntityBehaviour
    {
        public KrakenTentacle(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(LogicEntityProps.SHADOW_ALPHA, NumberOperator.Set, PROP_SHADOW_ALPHA));
        }

        #region 回调
        public override void Init(Entity boss)
        {
            base.Init(boss);
            stateMachine.Init(boss);
            stateMachine.StartState(boss, STATE_HIDDEN);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            stateMachine.UpdateAI(entity);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            stateMachine.UpdateLogic(entity);
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state == EntityCollisionHelper.STATE_EXIT)
                return;
            var other = collision.Other;
            var self = collision.Entity;
            if (self.IsDead)
                return;
            if (!other.Exists() || !other.IsHostile(self))
                return;
            var otherCollider = collision.OtherCollider;
            if (!other.IsInvincible() && other.Type == EntityTypes.PLANT)
            {
                self.BossCrush(otherCollider);
            }
        }

        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            if (entity.State == STATE_HIDDEN)
            {
                entity.Remove();
            }
            else
            {
                stateMachine.StartState(entity, STATE_DEATH);
            }
        }
        #endregion 事件

        public static void Recall(Entity entity)
        {
            if (entity.State == STATE_HIDDEN || entity.State == STATE_DISAPPEAR)
                return;
            stateMachine.StartState(entity, STATE_DISAPPEAR);
            stateMachine.StartSubState(entity, DisappearState.SUBSTATE_RECALLED);
        }
        public static void CommandAttack(Entity entity)
        {
            NextAppear(entity);
        }
        public static bool IsAutoAct(Entity entity) => entity.GetProperty<bool>(PROP_AUTO_ACT);
        public static void SetAutoAct(Entity entity, bool value) => entity.SetProperty(PROP_AUTO_ACT, value);
        public static float GetShadowAlpha(Entity entity) => entity.GetProperty<float>(PROP_SHADOW_ALPHA);
        public static void SetShadowAlpha(Entity entity, float value) => entity.SetProperty(PROP_SHADOW_ALPHA, value);
        public static int GetNextAction(Entity entity) => entity.GetProperty<int>(PROP_NEXT_ACTION);
        public static void SetNextAction(Entity entity, int value) => entity.SetProperty(PROP_NEXT_ACTION, value);
        public static readonly VanillaEntityPropertyMeta<bool> PROP_AUTO_ACT = new VanillaEntityPropertyMeta<bool>("auto_act", true);
        public static readonly VanillaEntityPropertyMeta<float> PROP_SHADOW_ALPHA = new VanillaEntityPropertyMeta<float>("shadow_alpha", 0f);
        public static readonly VanillaEntityPropertyMeta<int> PROP_NEXT_ACTION = new VanillaEntityPropertyMeta<int>("next_action", ACTION_GATLIN);
        public const int STATE_IDLE = VanillaBossStates.IDLE;
        public const int STATE_APPEAR = VanillaBossStates.APPEAR;
        public const int STATE_STUNNED = VanillaBossStates.STUNNED;
        public const int STATE_DEATH = VanillaBossStates.DEATH;
        public const int STATE_DISAPPEAR = VanillaBossStates.KRAKEN_TENTACLE_DISAPPEAR;
        public const int STATE_WEAPON = VanillaBossStates.KRAKEN_TENTACLE_WEAPON;
        public const int STATE_SMASH = VanillaBossStates.KRAKEN_TENTACLE_SMASH;
        public const int STATE_HIDDEN = VanillaBossStates.KRAKEN_TENTACLE_HIDDEN;

        public const int ANIMATION_STATE_IDLE = 0;
        public const int ANIMATION_STATE_APPEAR = 1;
        public const int ANIMATION_STATE_STUNNED = 2;
        public const int ANIMATION_STATE_DEATH = 3;
        public const int ANIMATION_STATE_DISAPPEAR = 10000;
        public const int ANIMATION_STATE_WEAPON = 10001;
        public const int ANIMATION_STATE_SMASH = 10002;
        public const int ANIMATION_STATE_HIDDEN = 10003;

        public const int ACTION_GATLIN = 0;
        public const int ACTION_CANNON = 1;
        public const int ACTION_LASER = 2;
        public const int ACTION_SUMMON = 3;
        public const int ACTION_SMASH = 4;

        public const int WEAPON_GATLIN = 0;
        public const int WEAPON_CANNON = 1;
        public const int WEAPON_LASER = 2;
        public const int WEAPON_SUMMON = 3;

        public static int[] actionPool = new int[]
        {
            ACTION_GATLIN,
            ACTION_CANNON,
            ACTION_LASER,
            ACTION_SUMMON,
            ACTION_SMASH,
        };

    }
}
